    p.part='body';arms=[[(24,26),(16,31+s/3),(10,27+s/2)],[(39,26),(47+s/3,30),(53,25-s/2)]];legs=[[(26,40),(21-s/2,49),(20-s/2,57)],[(36,40),(42+s/2,49),(43+s/2,56)]]
    if pose=='windup':arms[1]=[(39,26),(45,20),(42,14)]
    if pose=='attack':arms[1]=[(39,26),(48,26),(55,30)]
    for i,pts in enumerate(arms+legs):
        p.joint(pts,6,'b','B','d')
        for x,y in pts:p.poly([(x-3,y-2),(x+2,y-3),(x+3,y),(x+2,y+3),(x-2,y+3)],'B',True);p.poly([(x-1,y-1),(x+1,y-1),(x+1,y+1),(x-1,y+1)],'t');p.cluster(x,y,['y'])
        x,y=pts[-1]
        if i<2:p.poly([(x-3,y-2),(x+2,y-2),(x+4,y),(x+3,y+4),(x-2,y+3)],'y',True);p.line([(x,y),(x+3,y+1)],'B')
        else:p.poly([(x-4,y-2),(x+3,y-3),(x+6,y),(x+5,min(59,y+3)),(x-5,min(59,y+3))],'r',True);p.poly([(x-2,y-1),(x+2,y-1),(x+3,y+1),(x-3,y+1)],'R');p.line([(x,y),(x+3,y+1)],'p')
    p.poly([(24,23),(34,22),(40,27),(41,35),(36,43),(26,42),(21,36),(20,29)],'r',True);p.poly([(25,26),(31,25),(33,30),(31,38),(27,40),(23,35)],'R');p.poly([(26,27),(29,27),(30,31),(27,34),(25,32)],'p');p.poly([(34,26),(38,29),(38,34),(35,37),(33,33)],'R');p.line([(32,26),(33,40)],'y',2);p.cluster(32,30,['i']);p.poly([(26,22),(31,19),(38,23),(34,26)],'v',True);p.line([(28,22),(32,21),(35,23)],'l')
    p.part='head';p.pivot=(36,17);p.poly([(25,10),(29,5),(38,5),(44,10),(46,18),(45,24),(40,29),(31,27),(26,23),(23,16)],'t',True);p.poly([(28,11),(31,8),(36,8),(40,11),(42,16),(40,23),(35,25),(29,22),(26,17)],'y');p.poly([(29,12),(33,10),(36,12),(34,15),(28,15)],'i');p.eye(39,16,pose=='hit','C');p.line([(28,17),(33,18)],'o',2);p.poly([(39,20),(45,19),(48,22),(45,25),(39,24)],'y',True);p.line([(40,21),(45,22)],'i');p.line([(31,23),(36,25),(43,24)],'r',2);p.line([(34,23),(34,26)],'B');p.line([(38,24),(38,27)],'B');p.line([(32,9),(30,14),(32,18)],'B');p.line([(41,11),(40,15),(42,18)],'B');p.cluster(28,20,['yB','Bt'])
    p.poly([(23,11),(26,6),(29,2),(37,3),(41,7),(45,10),(42,13),(34,11),(26,14)],'v',True);p.poly([(27,8),(30,5),(35,5),(39,9),(35,10),(29,9)],'V');p.line([(29,6),(34,6)],'l');p.oval((41,5,46,10),'y','o');p.cluster(42,6,['i'])
    # Independent strings follow transformed limb end points; bar stays fixed.
    p.part='fixed'
    for i,pts in enumerate(arms+legs):
        x,y=pts[-1];p.part='body';ex,ey=p.point(x,y);p.part='fixed';p.line([((10,51,22,42)[i],7),(ex,ey)],'s')
