def totem(pose,cell):
    p=Pixels(pose,cell);s=SWING[pose]
    if pose=='dead':
        for x,y,w in [(11,54,8),(30,52,10),(49,54,9)]:wood(p,[(x-w,y-3),(x-w+3,y-6),(x+w-3,y-5),(x+w,y),(x+w-2,59),(x-w+2,60)]);p.line([(x-3,y),(x+3,y)],'o',2);p.poly([(x+1,y),(x+4,y+1),(x+4,y+3),(x,y+3)],'t');p.line([(x-2,y+4),(x+4,y+4)],'d')
        p.poly([(35,52),(39,46),(43,47),(46,53)],'F',True);p.line([(40,49),(42,52)],'a');return p.im
    p.part='body';p.joint([(18,40),(10,39+s/3),(8,30+s/3)],5,'f','F','c');p.joint([(47,40),(54,35-s/3),(55,27-s/2)],5,'f','F','c')
    for x,y in [(8,30+s/3),(55,27-s/2)]:p.poly([(x-4,y-4),(x+3,y-4),(x+5,y),(x+2,y+4),(x-3,y+3)],'b',True);p.poly([(x-2,y-2),(x+2,y-2),(x+2,y+1),(x-1,y+2)],'B');p.line([(x-1,y-2),(x+2,y-1)],'t')
    for j,(cx,cy,w,h) in enumerate([(32,47,15,12),(33,31,12,11),(34,15,10,10)]):
        x=cx+(s/3 if j%2 else -s/4);y=cy
        wood(p,[(x-w,y-h+3),(x-w+3,y-h),(x+w-3,y-h+1),(x+w,y-h+5),(x+w-1,y+h-2),(x+2,y+h),(x-w+2,y+h-1)]);p.poly([(x-w+3,y-h+3),(x-3,y-h+1),(x+1,y-3),(x-2,y+h-3),(x-w+3,y+h-4)],'B');p.poly([(x-2,y-h+2),(x+w-3,y-h+4),(x+w-2,y),(x+2,y-1)],'t');p.line([(x-w+4,y-h+3),(x-3,y-h+2)],'y');p.poly([(x-w+4,y-2),(x-3,y),(x-w+5,y+3)],'o');p.poly([(x+3,y),(x+w-3,y-3),(x+w-4,y+2)],'o');p.line([(x-w+6,y),(x-4,y+1)],'e',2);p.line([(x+4,y),(x+w-4,y-1)],'e',2)
        p.poly([(x-1,y-1),(x+3,y),(x+5,y+5),(x+1,y+7),(x-3,y+5)],'B',True);p.poly([(x,y),(x+2,y+1),(x+3,y+4),(x,y+4)],'t');p.line([(x-6,y+7),(x-1,y+8),(x+5,y+7)],'o',2);p.cluster(x-4,y+7,['yi']);p.cluster(x+2,y+7,['yi']);p.line([(x-w+5,y+2),(x-w+7,y+5)],'d');p.cluster(x+w-5,y+3,['BB','db']);p.line([(x-5,y-h+5),(x-7,y-h+8)],'d')
    if pose=='attack':
        x=33+s/3;p.poly([(x-7,33),(x+8,32),(x+10,36),(x+7,41),(x-4,41),(x-8,37)],'o',True);p.line([(x-5,34),(x+6,33)],'e',2);p.poly([(x-4,34),(x-2,34),(x-2,37),(x-3,38)],'i');p.poly([(x+3,34),(x+5,34),(x+4,38)],'y');p.line([(x-3,39),(x+4,39)],'B')
    p.part='fixed';p.poly([(17,57),(45,57),(47,60),(16,60)],'b',True);p.line([(19,58),(43,58)],'t')
    p.part='head';p.pivot=(34,13)
    for x,y in [(23,7),(28,4),(34,2),(39,4),(46,7)]:p.poly([(x-2,13),(x-3,y+2),(x,y),(x+2,y+2),(x+2,13)],'F',True);p.line([(x,y+3),(x,11)],'a');p.cluster(x,8,['U'])
    return p.im
